local UT=(getgenv and getgenv()) or _ENV or _G
local qB={} for i=97,122 do qB[#qB+1]=string.char(i) end
local Yb={12,15,1,4,19,20,18,9,14,7}
local ih="" for i=1,#Yb do ih=ih..qB[Yb[i]] end
local CF=UT and UT[ih]
local cH=type(CF)=="function"
if cH then
local mF={8,15,15,11,6,21,14,3,20,9,15,14}
local Wt="" for i=1,#mF do Wt=Wt..qB[mF[i]] end
local cj={18,5,19,20,15,18,5,6,21,14,3,20,9,15,14}
local gb="" for i=1,#cj do gb=gb..qB[cj[i]] end
local YT=UT[Wt]
local OV=UT[gb]
local Gh=false
if type(YT)=="function" and type(OV)=="function" then
local GF=function() return 5 end
local WN=pcall(YT,GF,function() return -777 end)
if WN and GF()==-777 then
local Mn=pcall(OV,GF)
Gh=(Mn and GF()==5)
end
if not Gh then pcall(OV,GF) end
if not Gh and type(UT.math)=="table" and type(UT.math.abs)=="function" then
local IH=UT.math.abs
if IH(5)==5 then
local mB,QT=pcall(YT,IH,function() return -777 end)
if mB and IH(5)==-777 then
local SZ=pcall(OV,IH)
Gh=(SZ and IH(5)==5)
if not Gh then pcall(OV,IH) UT.math.abs=(type(QT)=="function" and QT) or function(v) if v<0 then return -v end return v end end
end
end
end
if Gh then
local Kh={CF,YT,OV}
local EX=UT.string
if type(EX)=="table" then
Kh[#Kh+1]=EX.char Kh[#Kh+1]=EX.byte Kh[#Kh+1]=EX.sub Kh[#Kh+1]=EX.rep Kh[#Kh+1]=EX.len
end
if type(UT.table)=="table" and UT.table.concat then Kh[#Kh+1]=UT.table.concat end
if UT.pcall then Kh[#Kh+1]=UT.pcall end
if type(UT.math)=="table" and UT.math.floor then Kh[#Kh+1]=UT.math.floor end
for Sp=1,#Kh do local zt=Kh[Sp] if type(zt)=="function" then pcall(OV,zt) end end
end
end
end
if not cH then return nil end

